export class RbDetailDrawer extends HTMLElement {
  static get observedAttributes() { return ['ref', 'open', 'data-position']; }
  private startY = 0;
  private startHeight = 0;
  private dragging: 'resize' | 'dismiss' | false = false;
  private _restoreHeight = '';      // BUG3: height to restore when expanding from minimized
  private mouseResizing = false;    // BUG2: desktop grab-bar resize in progress
  private mouseMoved = false;
  private startBottom = 0;          // v0.6.95: drawer's actual bottom edge at drag-start (position-aware resize)
  private chatPanel: ChatPanel | null = null;
  private _mode: 'chat' | 'detail' | 'preview' = 'chat';
  // R34.7/R-E: host-registered context-verb providers (model registers actionsForContext); the shared drawer composes
  // the universal R-A A1 default + these on EVERY drawer usage. _shownType/_shownRef = last detail (for refreshActions).
  private _actionProviders: Array<(type: string, ref: string) => { verb: string; label: string; primary?: boolean }[]> = []; // legacy resolved-action providers (back-compat)
  private _declProviders: Array<() => ActionDecl[]> = []; // R40.37: declaration providers; resolved ONCE via applicableActionsFor in universalActionBar
  private _hasActiveDiagram = false; // R40.37: the shared bar's applicability ctx (R33.9 membership verbs' when-predicate); tracked from rb-active-diagram
  private _barSubRef = ''; private _barUnsub: (() => void) | null = null; // R40.45: the action bar's own ViewBus subscription (re-derive controls' visibility on unit-changed)
  private _currentSlotUuid = ''; private _csPinUnsub: (() => void) | null = null; // R40.57/R40.58 D3: the ONE live current-slot uuid (from the recompute source) + the CurrentSprint-pin subscription — taskRole is DERIVED from these at render (NO baked pinRole copy)
  private _shownType = ''; private _shownRef = '';

  // [impl:uuid:94f6e1f8-84a8-4ca5-9a44-6108ef6201bc] R20.6 selectionDriven drawer
  connectedCallback(): void {
    this.render();
    this.observePosition(); // R31.9: drive data-position (inline compartment ≥1025 / bottom drawer ≤1024) by container width — ONE instance, CSS-responsive
    const handle = this.querySelector('.drawer-handle');
    if (handle) {
      handle.addEventListener('touchstart', this.onTouchStart, { passive: true });
      handle.addEventListener('touchmove', this.onTouchMove, { passive: false });
      handle.addEventListener('touchend', this.onTouchEnd);
      handle.addEventListener('mousedown', this.onMouseDown); // BUG2: desktop resize
    }
    document.addEventListener('keydown', this.onKeyDown);
    document.addEventListener('selection-changed', this.onSelectionChanged);
    document.addEventListener('rb-drawer-action', this.onUniversalAction); // R-A A1: Scenario/Edit handled universally in the shared drawer
    document.addEventListener('rb-active-diagram', this.onActiveDiagram); // R40.37: track hasActiveDiagram for the applicability ctx (R33.9 membership verbs)
    document.addEventListener('rb-drawer-detail-shown', this.onDetailShown); // R40.24: SINGLE trigger — the type signal (from render OR box-select) drives the action bar here, no orphaned signal
    registerUniversalActions(this); // R35.1: self-register the view-independent item-action provider+handler (vcard/preview/newtab/proxy) — drawer loads everywhere → fires in room/trace/model
    // R40.57/R40.58 D3: subscribe the CurrentSprint pin (the SAME viewBusKey the tree uses, rb-trace-tree:107) so a live
    // make-current re-derives the action bar's taskRole; fetch the live current-slot once now. No baked pinRole — the
    // consumer derives at render → pin + action bar AGREE by construction.
    this._csPinUnsub = ViewBus.subscribe(viewBusKey({ type: 'CurrentSprint', uuid: 'current-sprint-singleton-0000-000000000001' }), () => { void this.refreshCurrentSlot(); });
    void this.refreshCurrentSlot();
  }

  // R40.57/R40.58 D3: fetch the ONE live current-slot uuid from the recompute source (/api/trace/children/<CS>?mode=trace
  // — per-request slotsFrom, NEVER the stale persisted model.slots snapshot) and re-derive the action bar. The current
  // slot is the recompute child stamped role:'current' (from slotsFrom's slot classification). HONEST ABSENCE: no such
  // child → _currentSlotUuid '' → every task derives 'other' → Set-Current shows on all (a guess is never made).
  // [impl:uuid:f5928a3b-0e42-4af8-973c-6f71a31d5be4] RbDetailDrawer.refreshCurrentSlot — derive-at-render from the live CurrentSprint pin (R40.57 lifecycle half)
  private async refreshCurrentSlot(): Promise<void> {
    const CS = 'current-sprint-singleton-0000-000000000001';
    try {
      const res = await fetch(`/api/trace/children/${encodeURIComponent(CS)}?mode=trace`);
      const data = res.ok ? await res.json() : null;
      const kids: Array<{ uuid?: string; role?: string }> = Array.isArray(data?.children) ? data.children : [];
      this._currentSlotUuid = bareUuid(kids.find((k) => k.role === 'current')?.uuid || '');
    } catch { this._currentSlotUuid = ''; } // honest absence on fetch failure — never a stale guess
    if (this._shownType) void this.universalActionBar(this._shownType, this._shownRef); // re-derive the bar with the fresh current
  }

  // R-A A1 (universal default verbs): the shared drawer ITSELF handles ◆ Scenario / ✎ Edit for ANY scenario-instance
  // detail — Scenario → the /scenario?ior focused view, Edit → the scenario editor (scenarioEditorHref). Host-specific
  // verbs are ignored here (their host handles them). Ref = the action's ref, else the last-shown detail ref.
  // [impl:uuid:005dbd3e-19e3-473f-944b-96c4e8053b4a] RbDetailDrawer.onUniversalAction (Method 276e4981, Class d86af73d, off UC 8106d378) — R34.1 (R-A A1): universal ◆Scenario/✎Edit handler. verb-listing crossRef a1a5be99; default-pair crossRef ffd44b17 (R34.7). Arrow-field kept (lexical this for the listener; PO/req = no method conversion).
  // [impl:uuid:7557bd7c-7e23-43c3-9772-c4189a87b434] RbDetailDrawer.onUniversalAction (R40.28 new-tab open — 3rd increment on Method 276e4981, DISTINCT from 005dbd3e/R34.1, R30.11 no-re-credit)
  private onUniversalAction = (e: Event): void => {
    const d = (e as CustomEvent<{ verb?: string; ref?: string }>).detail;
    const verb = d?.verb || '';
    if (verb !== 'scenario' && verb !== 'edit') return; // A1 defaults ONLY — host/type verbs handled by their own provider (no reverse regression)
    const rawRef = d?.ref || this._shownRef;
    if (!rawRef) return;
    // R40.28 (Tron): the A1 default ◆Scenario / ✎Edit ALWAYS open in a NEW TAB — never navigate the current tab (he
    // loses his place, the real cost on a phone). ★ iOS HAZARD (AC-7): window.open is popup-BLOCKED unless called
    // SYNCHRONOUSLY inside the tap handler — if we await first (a fetch/resolve) the tab silently never opens, and that
    // failure is invisible headless. So: open synchronously in-gesture; when a URL needs async resolution, open the tab
    // FIRST and set its location after (never await-then-open).
    // R35.2 NAV-RESOLVE: a SYNTHETIC view ref (dir:/file:/puml-src:/project:/rawbin:/mof-) carries its meaningful key in
    // the prefix — refUuid would strip it → only the FULL ref resolves via /api/ior to the REAL lazy-minted MODEL_STORE
    // unit. That needs a fetch → open the tab SYNC first, then point it once resolved (Scenario → uuid; Edit → store dir).
    if (isSyntheticRef(rawRef)) {
      const win = window.open('about:blank', '_blank'); // SYNC in-gesture open (iOS-safe); pointed after the async resolve
      void resolveRefUnit(rawRef).then((r) => { // inc-3: shared resolver (was an inline synthetic-regex+fetch — now can't drift from detail)
        const u = r?.uuid; if (!u) { win?.close(); return; }
        const url = verb === 'scenario' ? `/scenario?ior=${encodeURIComponent(u)}` : scenarioEditorHref(u, 'data/model-store/index');
        if (win) win.location.href = url; else window.open(url, '_blank'); // fallback if the sync open was itself blocked
      }).catch(() => { win?.close(); /* resolve failed → close the placeholder, no dead tab */ });
      return;
    }
    const uuid = refUuid(rawRef) || rawRef;
    if (!uuid) return;
    const url = verb === 'scenario' ? `/scenario?ior=${encodeURIComponent(uuid)}` : scenarioEditorHref(uuid);
    window.open(url, '_blank'); // SYNC new-tab open inside the tap handler (uuid resolved synchronously above — no await before open)
  };

  disconnectedCallback(): void {
    this._barUnsub?.(); this._barUnsub = null; this._barSubRef = ''; // R40.45: release the action-bar re-derive subscription
    this._csPinUnsub?.(); this._csPinUnsub = null; // R40.57/R40.58 D3: release the CurrentSprint-pin subscription
    const handle = this.querySelector('.drawer-handle');
    if (handle) {
      handle.removeEventListener('touchstart', this.onTouchStart);
      handle.removeEventListener('touchmove', this.onTouchMove);
      handle.removeEventListener('touchend', this.onTouchEnd);
      handle.removeEventListener('mousedown', this.onMouseDown);
    }
    document.removeEventListener('mousemove', this.onMouseMove);
    document.removeEventListener('mouseup', this.onMouseUp);
    document.removeEventListener('keydown', this.onKeyDown);
    document.removeEventListener('selection-changed', this.onSelectionChanged);
    document.removeEventListener('rb-drawer-action', this.onUniversalAction);
    document.removeEventListener('rb-active-diagram', this.onActiveDiagram);
    document.removeEventListener('rb-drawer-detail-shown', this.onDetailShown); // R40.24
    this._posRo?.disconnect(); this._posRo = null; // R31.9: stop the container-query position driver
  }

  // [impl:uuid:e927ecfe-619c-49f2-9ee4-dc82340f6433] R30.22 RbDetailDrawer.onSelectionChanged — selection-driven open (content-visible)
  private onSelectionChanged = (e: Event): void => {
    const selected = (e as CustomEvent).detail?.selected || [];
    if (selected.length === 1) {
      // R27.8(d) HARD INVARIANT (Tron): EACH select opens the drawer to peek + re-renders, from ANY prior state
      // (closed/removed/minimized/expanded), even re-selecting the SAME node. Clear currentRef so a same-ref re-render
      // isn't skipped; render directly when the ref attr is unchanged (attributeChangedCallback won't fire for it).
      const ref = selected[0];
      const dp = this.detailPanel; if (dp) dp.dataset.currentRef = '';
      const sameRef = this.getAttribute('ref') === ref;
      const wasOpen = this.hasAttribute('open');                // capture BEFORE mutating
      this.setAttribute('open', '');
      if (!wasOpen) this.openExpanded();                        // R30.22: content-select opens EXPANDED (visible), not peek — supersedes R27.8(B) closed→peek for content. ALREADY OPEN → PRESERVE state.
      this.setAttribute('ref', ref);
      if (sameRef) this.renderDetailForRef(ref);
    } else if (selected.length === 0) {
      // [impl:uuid:c3c70517-b56c-4765-94ae-cb677601f99c] R20.6 emptyShowsChat
      this.removeAttribute('ref');
      const dp = this.detailPanel;
      if (dp) dp.dataset.currentRef = '';
      this.tearDownTransientDetail(); // R31.4 INV-T1: deselect (empty selection) kills the terminal ws + sm_ session
      if (this.chatPanel) this.setMode('chat');
    }
  };

  // R30.22: open the drawer EXPANDED with the body visible (content-height), NOT the R27.8 peek — so a
  // detail-select shows its content immediately (no grab-bar click). X→minimize-peek, grab-bar→toggle,
  // ESC→close all remain unchanged; only the closed→open transition for a content-select changes.
  private openExpanded(): void {
    this.removeAttribute('minimized');
    const body = this.querySelector('.drawer-body') as HTMLElement | null;
    if (body) body.style.display = 'flex';
  }

  attributeChangedCallback(name: string): void {
    if (name === 'ref') {
      const ref = this.getAttribute('ref');
      if (ref) {
        const wasOpen = this.hasAttribute('open');            // capture BEFORE opening
        this.setAttribute('open', '');
        if (!wasOpen) this.openExpanded();                    // R30.22: content-ref opens EXPANDED (visible), not peek; already-open → PRESERVE state
        this.renderDetailForRef(ref);
      } else {
        this.removeAttribute('open');
      }
    } else if (name === 'data-position') { // R31.5.7: reactive position flip (inline↔bottom)
      this.applyPosition((this.getAttribute('data-position') as 'inline' | 'bottom') || 'bottom');
    }
  }

  // [impl:uuid:6e2d4b81-9a3c-4f57-b8e0-1d7c3a5f9e26] RbDetailDrawer.applyPosition (Method d48cc0ce, off UC 0f08964b, Class d86af73d)
  // R31.5.7 (drawer = Details compartment, THE CRUX): thin PRESENTATION-APPLICATION method, LAYOUT-ONLY. Sets the
  // data-position attr → app.css branches (inline = position:static in-flow [D] strip segment / bottom = position:fixed
  // as today); re-fit rides the EXISTING ResizeObserver / attributeChangedCallback. Touches NOTHING in the detail-render
  // flow / scroll / grab-bar / expand-minimize / in-room R30.20 X→chat — ONE component, position=mode (NO 2nd
  // full-width-drawer fork = the regression Tron flagged). Default (no attr) = today's bottom. Driven by the SAME
  // container-query as 5.4 (landscape→inline / portrait→bottom). AC-INV-PRESENTATION: same instance, both positions,
  // same functional tests — only computed layout differs.
  applyPosition(pos: 'inline' | 'bottom'): void {
    if (this.getAttribute('data-position') !== pos) this.setAttribute('data-position', pos);
    // R31.9: entering desktop (inline Details-compartment) CLEAR the stale bottom-drawer drag height (onTouchMove :384 /
    // stickyBottom set this.style.height) so it can't fight the flex:1 compartment = the resize-break Tron reported.
    // Bottom keeps its drag height (height is the resize axis there). This is the "clear stale inline height across BP" fix.
    if (pos === 'inline') { this.style.height = ''; this.style.maxHeight = ''; this.style.transform = ''; }
  }

  private _posRo: ResizeObserver | null = null;
  // [impl:uuid:240c539f-4c32-40e8-b40f-856dcb3daf6b] RbDetailDrawer.observePosition (Method e8097351, off UC cc45a580, Class d86af73d)
  // R31.9 container-query DRIVER (load-bearing): observe the HOST CONTAINER width → drive the existing applyPosition
  // (R31.5.7 d48cc0ce) so the ONE drawer instance transitions inline(≥1025 Details-compartment)↔bottom(≤1024 drawer)
  // via CSS [data-position] — NO JS instance-switch, NO re-mount (same DOM node), NO hard-@media jump. Observes the
  // PARENT (not self → no feedback loop) mirroring RbStrip.observeContainer (rb-strip.ts:81). Wires the previously-dead
  // R31.5.7 data-position mechanism (0 callers before). Cleaned up in disconnectedCallback.
  private observePosition(): void {
    if (this.getAttribute('data-context') === 'room-chat') return; // R31.12 #1: the in-room chat sheet OPTS OUT — no data-position driver (R31.9 was /trace+SM-designed); stays the base bottom chat sheet
    if (this._posRo) return;
    const host = this.parentElement || document.body; // .trace-page / .room-view / editor-area — its width crosses the 1025 BP
    const decide = (): void => this.applyPosition((host.getBoundingClientRect().width || window.innerWidth) >= 1025 ? 'inline' : 'bottom');
    this._posRo = new ResizeObserver(() => decide());
    this._posRo.observe(host);
    decide(); // initial position — correct on first paint (no jump)
  }

  private _graph: any = null;
  set graph(g: any) { this._graph = g; }
  // R37.24 inc2 AXIS-2: _fallbackGraph DELETED — it was the thin second model source. The element fetches the FULL unit.

  // [impl:uuid:dbddf408-60f3-4094-91b6-268861d651c6] R20.10 renderDetailForRef
  private async renderDetailForRef(ref: string): Promise<void> {
    this.setMode('detail');
    const panel = this.detailPanel;
    if (!panel || panel.dataset.currentRef === ref) return;
    // R37.24 inc2 AXIS-1/2: the drawer is a CONTAINER. It MOUNTS the type element (REUSING it when the tag is unchanged so
    // the double-invoke per select never creates two elements) + sets its ref; the ELEMENT owns render (its RbDetailBase
    // funnel = one render per ref-change) and its ONE model source (real graph ELSE fetch the full unit). DELETED: the
    // drawer's own render, the el.graph FALLBACK-thin source (resolveDetailUnit/_fallbackGraph), and the dataset.rendering
    // double-render guard (it guarded the DRAWER's render — retired; the element's funnel dedupes now).
    const colonIdx = ref.indexOf(':');
    const rawType = colonIdx > 0 ? ref.slice(0, colonIdx) : 'unknown';
    const rawKey = colonIdx > 0 ? ref.slice(colonIdx + 1) : ref;
    // GENUINE room collection (members-/files-<roomUuid>) — bespoke inline render, no detail element → the drawer owns its bar.
    if (rawType === 'collection' && /^(members|files)-/.test(rawKey)) {
      this.showActionsForType(rawType, ref);
      const uuid = rawKey;
      const parts = uuid.split('-');
      const kind = parts[0];
      const roomUuid = parts.slice(1).join('-');
      if (!roomUuid) return;
      panel.dataset.currentRef = ref;
      panel.innerHTML = `<h3 style="color:white;margin:0 0 8px;font-size:0.9rem">${kind === 'members' ? 'Members' : 'Files'}</h3><div class="dv-loading">Loading...</div>`;
      try {
        const res = await fetch(`/api/trace/children/${roomUuid}`);
        const data = await res.json();
        const coll = (data.children || []).find((c: any) => c.uuid === uuid);
        const children = coll?.children || [];
        panel.innerHTML = `<h3 style="color:white;margin:0 0 8px;font-size:0.9rem">${kind === 'members' ? 'Members' : 'Files'} (${children.length})</h3>` +
          (children.length === 0 ? '<div class="dv-empty">None</div>' :
          children.map((c: any) => `<div class="dv-link" data-ref="${(c.type || '').toLowerCase()}:${c.uuid}"><span class="dv-rel">${c.type}</span><span class="dv-link-title">${c.name || c.uuid}</span></div>`).join(''));
      } catch { panel.innerHTML = '<div class="dv-empty">Failed to load</div>'; }
      return;
    }
    // inc-3: the ONE shared resolver → {type,uuid} drives the tag. (No graph resolve here — the element owns its model source.)
    const resolved = await resolveRefUnit(ref);
    const type = (resolved?.type || rawType).toLowerCase();
    const uuid = resolved?.uuid || (isSyntheticRef(ref) ? ref : rawKey);
    // R30.3: Sprint / CurrentSprint render inline (no detail element) → the drawer owns their bar signal.
    if (type === 'sprint' || type === 'currentsprint') {
      this.showActionsForType(type, ref);
      await this.renderSprintDetail(uuid, type, panel);
      return;
    }
    const tagMap: Record<string, string> = {
      requirement: 'rb-requirement-detail', task: 'rb-task-detail', usecase: 'rb-usecase-detail',
      changerequest: 'rb-requirement-detail', // R40.10 BUG A: ChangeRequest uses RequirementTemplate → REUSE its detail (renders the reason)
      class: 'rb-class-detail', method: 'rb-method-detail', implementation: 'rb-implementation-detail',
      test: 'rb-test-detail', file: 'rb-file-detail', webitem: 'rb-webitem-detail',
      otmuxpane: 'rb-terminal-detail', // R31.4 DRY: Server Manager terminal = a detail-view (tag string only → no xterm in /trace bundles)
      feature: 'rb-feature-detail', // R31.8b/c: FeatureManager view = a detail-view (tag string only → stays out of /trace)
      profile: 'rb-profile-detail', // R31.8c NODE-4: granted-user detail (revoke); tag string only
      diagram: 'rb-diagram-detail', // R32.4: MDA SVG diagram surface
      modelelement: 'rb-modelelement-detail', // R32.10 (INV-M2): MDA M1 element detail
      'puml-src': 'rb-modelelement-detail', // R33.1.1: a puml/ source-.puml leaf mounts rb-modelelement-detail
    };
    const tag = tagMap[rawType] || tagMap[type] || 'rb-detail-view'; // rawType FIRST preserves synthetic bespoke views; else resolved type; else the generic default
    panel.dataset.currentRef = ref;
    // MOUNT once (reuse the element when the tag is unchanged → the double-invoke per select updates the ref, never a 2nd
    // element). Pass the REAL graph ONLY (this._graph — may be null in scenario-view); the element derives from that ONE
    // source (graph obj ELSE fetch-full) and dispatches rb-drawer-detail-shown on its OWN render (AXIS-3: bar ⟵ element ref).
    let el = panel.firstElementChild as (HTMLElement & { graph?: unknown }) | null;
    if (!el || String(el.tagName || '').toLowerCase() !== tag) {
      panel.innerHTML = '';
      el = document.createElement(tag) as HTMLElement & { graph?: unknown };
      if (this._graph) el.graph = this._graph;
      el.setAttribute('uuid', uuid);
      el.setAttribute('ref', ref); // set BEFORE append → connectedCallback renders once with the ref present
      panel.appendChild(el);
    } else {
      if (this._graph) el.graph = this._graph;
      el.setAttribute('uuid', uuid);
      el.setAttribute('ref', ref); // reuse: attributeChangedCallback → the element funnel renders once per ref-change (no-op if unchanged)
    }
  }

  // R37.24 inc2 AXIS-2: resolveDetailUnit + the _fallbackGraph it built are DELETED. That fallback was the THIN second
  // model source (a minimal TraceObject with name/status only) — the full-vs-thin content Tron photographed. The element
  // now derives from ONE source (RbDetailBase: real graph obj ELSE fetch the full /api/ior unit ELSE honest-empty).

  // [impl:uuid:0267036c-ec5a-4e13-a74e-1a89f45412b3] RbDetailDrawer.renderSprintDetail — R30.3 sprint selection populates the detail drawer
  // R30.3: Sprint / CurrentSprint nodes come from /api/trace/sprints (not the in-memory graph), so the
  // generic rb-detail-view resolves empty. Render sprint details directly (name, goal, task list) — like the collection case.
  private async renderSprintDetail(uuid: string, type: string, panel: HTMLElement): Promise<void> {
    panel.dataset.currentRef = `${type}:${uuid}`;
    panel.innerHTML = '<div class="dv-loading">Loading...</div>';
    try {
      const res = await fetch(`/api/ior/ior:instance:${uuid}`);
      const m = (await res.json())?.unit?.model || {};
      const goal = String(m.goal || m.sprintGoal || m.description || '');
      const tasks: string[] = Array.isArray(m.tasks) ? m.tasks : [];
      const childRes = await fetch(`/api/trace/children/${encodeURIComponent(uuid)}`);
      const kids = (await childRes.json().catch(() => ({})))?.children || [];
      panel.innerHTML =
        `<div class="dv-head"><span class="dv-type">${type}</span><h3 class="dv-title">${sprintDisplayName(String(m.name || uuid), m.number as number | undefined)}</h3><code class="dv-uuid">${uuid}</code></div>` + // R40.4 label carries the number
        (goal ? `<p style="color:rgba(255,255,255,0.7);font-size:0.78rem;margin:8px 0">${goal}</p>` : '') +
        `<div class="dv-scenario-children"><h4 style="font-size:0.75rem;color:rgba(255,255,255,0.5);margin-bottom:4px">Tasks (${tasks.length || kids.length})</h4>` +
        (kids.length === 0 ? '<div class="dv-empty">no tasks</div>' :
          kids.map((c: any) => `<div class="dv-link" data-ref="${String(c.type || 'task').toLowerCase()}:${c.uuid}"><span class="dv-rel">${c.type || 'Task'}</span><span class="dv-link-title">${c.name || c.uuid}</span></div>`).join('')) +
        `</div>`;
    } catch { panel.innerHTML = '<div class="dv-empty">Failed to load sprint</div>'; }
  }

  // [impl:uuid:e76330fe-e29d-4587-b113-a1ed940ce62c] R20.6 removeDefaultHighlight keep-X
  // [impl:uuid:2e4ff35c-6286-4400-a2c8-d6ebfde62638] R20.11 close
  close(): void {
    this.removeAttribute('ref');
    this.removeAttribute('open');
    this.removeAttribute('minimized'); this.removeAttribute('maximized');  // R27.8(b) + R31.4: clean slate
    this.style.height = '';
    this.style.maxHeight = '';
    const dp = this.detailPanel; if (dp) dp.dataset.currentRef = '';        // R27.8(b): so a later reopen RE-RENDERS (not the stale-ref no-op)
    const body = this.querySelector('.drawer-body') as HTMLElement | null; if (body) body.style.display = 'flex'; // R27.8(b): restore body (minimize set it none)
    this.tearDownTransientDetail(); // R31.4 INV-T1: ESC/full-close kills the terminal ws + sm_ session
    selectionModel.clear();
  }

  // R31.4 INV-T1 (auto-close): the terminal detail (rb-terminal-detail) owns a LIVE ws + a server-side grouped tmux
  // session — expensive, and it LEAKS if the element merely lingers in the DOM. Unlike a normal (persistent) detail,
  // it MUST NOT survive a drawer-away state — minimize/peek/close/empty-select keep the element mounted (body hidden,
  // no disconnectedCallback) so its teardown never fires → 14 orphaned sm_ sessions observed. FIX: explicitly REMOVE
  // the terminal element on those transitions → disconnectedCallback → RbTerminalDetail.teardown → ws.close → server
  // cleanup() kills the sm_ grouped session. Terminal-SPECIFIC by tag (persistent details correctly survive minimize/
  // peek); re-selecting the pane re-attaches via renderDetailForRef. Select-AWAY to another ref already tears down via
  // renderDetailForRef's panel.innerHTML='' — this covers the states that DON'T re-render.
  // [impl:uuid:cb153623-3acb-4c45-8dc8-e2bceeba4ae1] RbDetailDrawer.tearDownTransientDetail (R31.4 INV-T1 auto-close)
  private tearDownTransientDetail(): void {
    if (this.getAttribute('data-context') === 'room-chat') return; // R31.12 #1: the in-room chat sheet is NOT governed by the R31.4 terminal auto-close/teardown lifecycle
    const term = this.detailPanel?.querySelector('rb-terminal-detail');
    if (term) { term.remove(); const dp = this.detailPanel; if (dp) dp.dataset.currentRef = ''; } // remove → teardown → ws close → kill sm_ session; clear ref so a reopen re-renders
  }

// [impl:uuid:b53858c3-89ba-48ee-a659-2d03a3c88e51] impl:RbDetailDrawer.stickyBottom (split for RbDetailDrawer.c
// [impl:uuid:b708531d-4274-4987-b573-94fbf2e2cb88] impl:RbDetailDrawer.stickyBottom (split for RbDetailDrawer.o
// [impl:uuid:c1e90fe2-ea6d-4ada-abbd-09286a75bdfd] impl:RbDetailDrawer.stickyBottom (split for RbDetailDrawer.c
// [impl:uuid:868331a4-7890-4467-bb99-9aec0cb78f4b] impl:RbDetailDrawer.stickyBottom (split for RbDetailDrawer.s
  // [impl:uuid:d0235605-5d79-4411-a6ff-c72099ffd2f9] RbDetailDrawer.stickyBottom
  get body(): HTMLElement {
    let b = this.querySelector('.drawer-body') as HTMLElement;
    if (!b) { this.render(); b = this.querySelector('.drawer-body') as HTMLElement; }
    return b;
  }

  // [impl:uuid:aa585fcc-dfc1-42a8-a77d-0c0fb03ca5fd] RbDetailDrawer.stickyClose R19.33
  private render(): void {
    if (this.querySelector('.drawer-header')) return;
    this.innerHTML = `
      <div class="drawer-header">
        ${this.renderGrabBar()}
        <button class="drawer-max" title="Maximize">⛶</button>
        <button class="drawer-close" title="Close">✕</button>
      </div>
      <div class="drawer-actionbar" style="display:none;flex:0 0 auto;background:#161b22;border-bottom:1px solid #30363d"></div>
      <div class="drawer-body" style="display:flex;flex-direction:column">
        <div class="drawer-panel-chat" style="display:flex;flex-direction:column;flex:1;min-height:0"></div>
        <div class="drawer-panel-detail" style="display:none"></div>
        <div class="drawer-panel-preview" style="display:none"></div>
      </div>`;
    // R30.20 (mode-aware close): X returns detail→chat when a chat panel exists (in-room), else minimizes to peek
    // (trace context, or already in chat). ESC still fully CLOSES; grab-bar toggles peek↔expand via closeAndMinimize().
    this.querySelector('.drawer-handle')!.addEventListener('click', () => { if (this.mouseMoved) return; this.closeAndMinimize(); });
    this.querySelector('.drawer-max')!.addEventListener('click', () => this.toggleMaximize());
    this.querySelector('.drawer-close')!.addEventListener('click', () => this.closeOrReturn());
    // R33.6.5 item5: a button in the generic action-bar → emit rb-drawer-action {verb, ref}; the HOST view handles the verb.
    this.querySelector('.drawer-actionbar')!.addEventListener('click', (e) => {
      const verb = (e.target as HTMLElement).closest('[data-verb]')?.getAttribute('data-verb');
      if (verb) document.dispatchEvent(new CustomEvent('rb-drawer-action', { detail: { verb, ref: this.detailPanel?.dataset.currentRef || '' }, bubbles: true }));
    });
  }

  // [impl:uuid:cef954eb-443d-4969-b54f-1c92e3692392] RbDetailDrawer.setActions (item5, INV-1/3) — GENERIC fixed action-bar region: the HOST
  // supplies {verb,label}[]; renders a reused rb-strip; empty → hidden bar. Zero model specifics live in the shared
  // drawer (/trace + /scenario register no actions → bar stays hidden). A click emits rb-drawer-action (wired above).
  setActions(items: { verb: string; label: string; primary?: boolean }[]): void {
    const bar = this.querySelector('.drawer-actionbar') as HTMLElement | null;
    if (!bar) return;
    if (!items || !items.length) { bar.style.display = 'none'; bar.replaceChildren(); return; }
    // R-A A1: `primary` verbs (the universal ◆ Scenario / ✎ Edit default) render ORANGE (.da-btn variant); the rest neutral.
    const btn = (a: { verb: string; label: string; primary?: boolean }): string => `<button class="da-btn${a.primary ? ' da-btn-primary' : ''}" data-verb="${a.verb}" style="background:${a.primary ? '#fb8c00' : '#21262d'};color:${a.primary ? '#1a1a1a' : '#e6edf3'};border:1px solid ${a.primary ? '#fb8c00' : '#30363d'};border-radius:6px;padding:6px 12px;font:13px system-ui;cursor:pointer;white-space:nowrap">${a.label}</button>`;
    const strip = document.createElement('rb-strip') as HTMLElement & { items?: { id: string; kind: string; content: string }[] };
    strip.items = [{ id: 'drawer-actions', kind: 'bar', content: `<div style="display:flex;gap:8px;padding:8px 10px;overflow-x:auto">${items.map(btn).join('')}</div>` }];
    bar.replaceChildren(strip);
    bar.style.display = '';
  }

  // [impl:uuid:e6870858-2f5b-4605-a2a7-31b366dd41e2] RbDetailDrawer.showActionsForType (item6, INV-2) — selection-driven: on each detail
  // render tell the HOST which TYPE is shown (rb-drawer-detail-shown {type,ref}) so it can setActions for that type;
  // the shared drawer never hardcodes actions. Cleared (setActions([])) when switching to chat / empty.
  // R40.24 SINGLE trigger: the drawer hears rb-drawer-detail-shown{type,ref} from ANY source — its own render dispatch
  // AND rb-active-diagram box-select — and drives the action bar HERE. Fixes the orphaned-signal regression: box-select's
  // {type:'modelelement'} was heard ONLY by model.ts (local shownRef), never reached universalActionBar, so element verbs
  // (incl Delete) never rendered while a diagram was open. One driver, no second driver in model.ts, no double-fire.
  private onDetailShown = (e: Event): void => { const d = (e as CustomEvent<{ type?: string; ref?: string }>).detail; void this.universalActionBar((d?.type || '').toLowerCase(), d?.ref || ''); };
  // R40.37: a diagram opened/closed → update the applicability ctx + re-resolve the bar (R33.9 membership verbs' when-predicate).
  private onActiveDiagram = (e: Event): void => { this._hasActiveDiagram = !!(e as CustomEvent<{ uuid?: string | null }>).detail?.uuid; if (this._shownType) void this.universalActionBar(this._shownType, this._shownRef); };

  private showActionsForType(type: string, ref: string): void {
    const t = (type || '').toLowerCase();
    document.dispatchEvent(new CustomEvent('rb-drawer-detail-shown', { detail: { type: t, ref }, bubbles: true })); // R40.24: DISPATCH-ONLY — the drawer's own onDetailShown listener drives universalActionBar (ONE trigger path; box-select's {modelelement} signal now reaches it too — no orphaned signal, no double-fire)
    // R34.5 (R-D1): a select→navigate that SHOWS a model-element detail (from diagram/detail-link/anywhere) also reveals
    // it in the tree — auto-expand the folder ancestor path via the EXISTING R33.7.4 onTreeReveal→revealModelElement→
    // expandPath (ride wholesale, NO new verb/Method). Was missing: rb-tree-reveal only fired on diagram-box-select.
    if (t === 'modelelement' && ref) document.dispatchEvent(new CustomEvent('rb-tree-reveal', { detail: { ref }, bubbles: true }));
  }

  // [impl:uuid:ffd44b17-5882-4d77-94d1-a3c03c07ffad] RbDetailDrawer.universalActionBar (Method 54acc696) — R34.7/R-E
  // unified with R-A A1 (793760f2): the SHARED drawer sets the action bar itself on EVERY detail render (all 7 drawer
  // usages), not just where a host listens. Composes the UNIVERSAL A1 default [◆ Scenario, ✎ Edit] (primary/orange,
  // handled by onUniversalAction) + every registered host provider's context verbs (model = actionsForContext, R33.9
  // reused verbatim). INV-E1 universal / E2 context-verbset (default everywhere + host verbs only where registered) /
  // E3 no-fork (setActions/actionsForContext unchanged; empty/chat → cleared bar).
  private async universalActionBar(type: string, ref: string): Promise<void> {
    this._shownType = type; this._shownRef = ref;
    // R40.45 CONTROLS-ARE-A-SURFACE: subscribe the action bar to the shown ref on the ONE bus so a unit-changed (approve→Done,
    // etc.) RE-DERIVES the whole bar from CURRENT status — every control whose visibility derives from unit state (Approve/
    // Decline hidden unless QA-Review, Set-as-Current per matrix, Open-Task-file always) re-evaluates on the SAME emit, never
    // latched at mount. Re-subscribe only when the shown ref changes (no churn; the notify→re-call hits this guard as a no-op).
    if (this._barSubRef !== ref) {
      this._barUnsub?.();
      this._barSubRef = ref;
      this._barUnsub = ref ? ViewBus.subscribe(viewBusKey(ref), () => { void this.universalActionBar(this._shownType, this._shownRef); }) : null; // R40.45: canonical key = matches the notify key by construction
    }
    if (!type || !ref || type === 'chat') { this.setActions([]); return; } // INV-E3: empty/chat clears the bar
    const defaults = [{ verb: 'scenario', label: '◆ Scenario', primary: true }, { verb: 'edit', label: '✎ Edit', primary: true }]; // R-A A1 universal default
    // R40.37: resolve action applicability ONCE here (no per-view if-chains). Providers SUPPLY declarations; the shared bar
    // filters by the selected unit's (type, status, kind) via applicableActionsFor. inc-3 (AC4): the REAL {type,kind} comes
    // from the shared resolveRefUnit — NEVER refUuid(ref) (refUuid('rawbin:diagram')→'diagram' stripped the prefix → missed
    // the kind → add-diagram never matched the diagrams container). status still comes from the resolved graph obj. Absent
    // status ⇒ status-gated actions (approve/decline) HIDE (never offer the impossible). This is the AC1..AC4 fix.
    const r = await resolveRefUnit(ref);
    if (this._shownRef !== ref) return; // a newer selection landed while awaiting → don't paint the stale ref's bar
    const uuid = r?.uuid || ref;
    const obj = this._graph?.get(uuid); // R37.24 inc2: real graph only — no fallback-thin source (deleted)
    const rModel = (r?.unit as { model?: Record<string, unknown> } | undefined)?.model;
    // R40.31(b) FIX (architect 624f5eba3): FRESH resolved status WINS, cache is the fallback. resolveRefUnit already
    // re-fetches /api/ior per callback (synthetic-ref.ts) so rModel.status is fresh; the old `obj?.status ?? rModel` let the
    // STALE cached graph obj.status SHADOW it → keys matched + callback fired but the bar re-derived the old status (the
    // live-render-never-worked root). Invert: rModel.status first, obj.status only when the resolve carried none.
    const unit = { type: r?.type || type, status: (rModel?.status as string | undefined) ?? obj?.status, kind: r?.kind ?? (obj as unknown as { kind?: string } | undefined)?.kind };
    // ed3442d10 / L15 FAIL-LOUD-UNRESOLVED: control visibility follows STATUS, never graph MEMBERSHIP. attachTaskStatus now
    // derives status at the /api/ior READ boundary so a real task always carries it — but an ABSENT status must NEVER
    // silently mean not-actionable (a data gap hiding a real action = the silent-swallow class). So it is OBSERVABLE
    // (console.error + a data attr a human AND a gate can read), not a quiet hide. Membership does not decide; status does.
    const statusUnresolved = (r?.type || type).toLowerCase() === 'task' && unit.status == null;
    if (statusUnresolved) {
      console.error(`[action-bar] ★ TASK status UNRESOLVED for ${ref} — controls suppressed on a DATA GAP, not a status decision (fail-loud, not silent-hide; ed3442d10/L15)`);
      this.setAttribute('data-status-unresolved', ref);
    } else { this.removeAttribute('data-status-unresolved'); }
    // R40.57/R40.58 D3: taskRole is DERIVED AT RENDER from the ONE live current-slot (NO baked pinRole copy in the payload
    // — that was the stale-able copy). Compare via bareUuid (D2, form-independent). Honest absence: no live current →
    // _currentSlotUuid '' → 'other' → Set-Current shows. The CurrentSprint-pin subscription re-derives this on a pin-move.
    const taskRole: 'current' | 'other' | undefined = (r?.type || type).toLowerCase() === 'task'
      ? (this._currentSlotUuid && bareUuid(ref) === this._currentSlotUuid ? 'current' : 'other')
      : undefined;
    const decls: ActionDecl[] = this._declProviders.flatMap((fn) => { try { return fn() || []; } catch { return []; } });
    const { offered } = applicableActionsFor(unit, { hasActiveDiagram: this._hasActiveDiagram, taskRole }, decls);
    const legacy = this._actionProviders.flatMap((fn) => { try { return fn(type, ref) || []; } catch { return []; } }); // back-compat path (empty once providers migrate to decls)
    // v0.8.114 (architect a38cd7c91): a VISIBLE '⚠ status unresolved' bar item so an unresolved TASK status reads LOUD to
    // TRON on-screen — not just the DOM attr + console (loud to a gate/dev, SILENT to him). An empty control-area otherwise
    // reads to the person-who-acts as a normal not-actionable task = the exact wrong impression the original defect gave.
    // Informational (no handler); it says the absence is a DATA GAP, not a status decision. This IS 'renders a LOUD state'.
    const unresolved = statusUnresolved ? [{ verb: 'status-unresolved', label: '⚠ status unresolved — data gap', primary: false }] : [];
    this.setActions([...defaults, ...offered, ...legacy, ...unresolved]);
  }

  // R34.7/R-E: a host registers its context verbs as a provider (model → actionsForContext); re-render so a provider
  // that registers AFTER the first detail still shows. refreshActions re-runs the bar for the current detail (host
  // context changed, e.g. rb-active-diagram → membership verbs recompute).
  registerActionProvider(fn: (type: string, ref: string) => { verb: string; label: string; primary?: boolean }[]): void {
    this._actionProviders.push(fn);
    if (this._shownType) void this.universalActionBar(this._shownType, this._shownRef);
  }
  // R40.37: register a DECLARATION provider (verbs + appliesTo), resolved once in universalActionBar via applicableActionsFor.
  registerActionDecls(fn: () => ActionDecl[]): void {
    this._declProviders.push(fn);
    if (this._shownType) void this.universalActionBar(this._shownType, this._shownRef);
  }
  refreshActions(): void { if (this._shownType) void this.universalActionBar(this._shownType, this._shownRef); }

  // R31.4 AC-maximize (Option A, PO-endorsed): full-viewport drawer = maximum terminal space, NO-disrupt — the grouped
  // attach shows the whole window (NO tmux zoom, which is a shared window property that would leak to other viewers →
  // options C/D true single-pane isolation deferred pending Tron). Toggles the `maximized` attr → app.css lifts the
  // drawer to fixed inset:0; the terminal's ResizeObserver auto-re-fits to the larger box. General to the shared drawer
  // (any detail can maximize). Cleared by minimize()/close() for a clean slate.
  private toggleMaximize(): void {
    if (this.hasAttribute('maximized')) { this.removeAttribute('maximized'); return; }
    this.removeAttribute('minimized');
    const body = this.querySelector('.drawer-body') as HTMLElement | null; if (body) body.style.display = 'flex'; // maximize implies expanded
    this.setAttribute('maximized', '');
  }

  setMode(m: 'chat' | 'detail' | 'preview'): void {
    this._mode = m;
    for (const [cls, active] of [['chat', m === 'chat'], ['detail', m === 'detail'], ['preview', m === 'preview']] as const) {
      const el = this.querySelector(`.drawer-panel-${cls}`) as HTMLElement;
      if (el) el.style.display = active ? (cls === 'chat' ? 'flex' : 'block') : 'none';
    }
  }

  // [impl:uuid:65f43714-97e3-4e70-b8ef-a0e6d88ed31d] R30.20 RbDetailDrawer.closeOrReturn
  // Mode-aware X: in a room (chat panel exists) a detail view steps BACK to chat instead of vanishing the room;
  // in trace context (no chat panel) or already in chat, minimize to peek. ESC still fully closes (separate handler).
  closeOrReturn(): void {
    if (this.chatPanel && this._mode === 'detail') this.setMode('chat');
    else this.minimize();
  }

  get chat(): ChatPanel | null {
    if (!this.chatPanel) {
      const panel = this.querySelector('.drawer-panel-chat') as HTMLElement;
      if (panel) this.chatPanel = new ChatPanel(panel);
    }
    return this.chatPanel;
  }

  get detailPanel(): HTMLElement {
    return this.querySelector('.drawer-panel-detail') as HTMLElement;
  }

  get previewPanel(): HTMLElement {
    return this.querySelector('.drawer-panel-preview') as HTMLElement;
  }

  // [impl:uuid:58abb87f-90c2-478c-8c4b-a7cb953519bf] R20.2 renderGrabBar
  private renderGrabBar(): string {
    return '<div class="drawer-handle"><div class="drawer-handle-bar"></div></div>';
  }

  // [impl:uuid:cea22d12-cdae-4c25-a1e8-4231b1d46eb1] R19.84 handleDragResize
  // [impl:uuid:79601135-a1b2-4c3d-8e4f-5a6b7c8d9e03] R19.86 dismiss threshold
  private onTouchStart = (e: TouchEvent): void => {
    const handle = this.querySelector('.drawer-handle');
    const t = e.target as Node;
    this.startY = e.touches[0].clientY;
    if (handle && (handle.contains(t) || t === handle)) {
      this.dragging = 'resize';
      this.startHeight = this.offsetHeight;
      this.style.transition = 'none';
      this.style.maxHeight = 'none';
    } else {
      this.dragging = false;
    }
  };

  private onTouchMove = (e: TouchEvent): void => {
    const touchY = e.touches[0].clientY;
    const dy = touchY - this.startY;
    if (this.dragging === 'resize') {
      e.preventDefault();
      const newH = this.startHeight + (this.startY - touchY);
      const clamped = Math.min(window.innerHeight * 0.95, Math.max(120, newH));
      this.style.height = `${clamped}px`;
    } else if (this.dragging === 'dismiss') {
      if (dy > 0) { this.style.transform = `translateY(${dy}px)`; e.preventDefault(); }
    } else if (dy > 10) {
      this.dragging = 'dismiss';
      this.style.transition = 'none';
    }
  };

  private onTouchEnd = (e: TouchEvent): void => {
    if (!this.dragging) return;
    const mode = this.dragging;
    this.dragging = false;
    this.style.transition = '';
    if (mode === 'resize') {
      const h = parseInt(this.style.height || '0');
      if (h < 120) { this.minimize(); } // BUG3: resize-to-tiny minimizes (peek), not close
    } else {
      const dy = e.changedTouches[0].clientY - this.startY;
      this.style.transform = '';
      if (dy > 80) this.minimize(); // BUG3: swipe-down minimizes (peek), not close
    }
  };

  // BUG3: minimize to a peek bar (header only); click the bar to expand. ESC still fully closes.
  // [impl:uuid:bfe09645-5e91-42e1-a843-c882b61be9b5] R25.4 RbDetailDrawer.minimize
  minimize(): void {
    if (this.hasAttribute('minimized')) return;
    this.removeAttribute('maximized'); // R31.4: minimize supersedes maximize
    this._restoreHeight = this.style.height || `${this.offsetHeight}px`;
    this.setAttribute('minimized', '');
    this.style.height = ''; this.style.maxHeight = ''; this.style.transform = '';
    const body = this.querySelector('.drawer-body') as HTMLElement | null; if (body) body.style.display = 'none';
    this.tearDownTransientDetail(); // R31.4 INV-T1: minimize/peek must kill the terminal ws + sm_ session (the leak: body hidden but element stayed mounted)
  }
  expand(): void {
    if (!this.hasAttribute('minimized')) return;
    this.removeAttribute('minimized');
    const body = this.querySelector('.drawer-body') as HTMLElement | null;
    if (body) body.style.display = 'flex';
    if (this._restoreHeight) this.style.height = this._restoreHeight;
  }

  // [impl:uuid:e42b85e8-d844-4e7b-be17-561a82d780b9] R27.8 RbDetailDrawer.closeAndMinimize
  // Grab-bar peek/expand orchestration: toggles minimized↔expanded (reuses R25.4 minimize()/expand()). Paired with
  // X→close() + open-minimized default (7029d8728): closed → open+minimized(peek) → grab-bar → expanded; X/ESC → close.
  closeAndMinimize(): void {
    if (this.hasAttribute('minimized')) this.expand(); else this.minimize();
  }

  // BUG2: desktop grab-bar resize — mirrors the touch handlers; move/up on document so the drag
  // continues off the handle. A mousedown with no movement falls through to the grab-bar peek toggle.
  // [impl:uuid:9d095150-0c3b-42bc-9763-1d79a46383f7] R25.4 RbDetailDrawer.onMouseDown (grab-bar pointer)
  private onMouseDown = (e: MouseEvent): void => {
    const handle = this.querySelector('.drawer-handle');
    if (!handle || !(handle.contains(e.target as Node) || e.target === handle)) return;
    this.startY = e.clientY; this.startHeight = this.offsetHeight;
    this.startBottom = this.getBoundingClientRect().bottom; // v0.6.95: anchor to the ACTUAL bottom edge (works in any layout/position, not just a viewport-bottom sheet)
    this.mouseResizing = true; this.mouseMoved = false;
    this.style.transition = 'none'; this.style.maxHeight = 'none';
    document.addEventListener('mousemove', this.onMouseMove);
    document.addEventListener('mouseup', this.onMouseUp);
    e.preventDefault();
  };
  private onMouseMove = (e: MouseEvent): void => {
    if (!this.mouseResizing) return;
    if (this.hasAttribute('minimized')) this.expand();
    this.mouseMoved = true;
    // v0.6.95: height = distance from the cursor to the drawer's anchored bottom edge — correct in
    // EVERY layout (was startHeight + Δ, which only held when the drawer bottom == viewport bottom → jumped after the media breakpoint repositioned it).
    const newH = this.startBottom - e.clientY;
    this.style.height = `${Math.min(window.innerHeight * 0.95, Math.max(120, newH))}px`;
  };
  private onMouseUp = (): void => {
    if (!this.mouseResizing) return;
    this.mouseResizing = false;
    this.style.transition = '';
    document.removeEventListener('mousemove', this.onMouseMove);
    document.removeEventListener('mouseup', this.onMouseUp);
    if (this.mouseMoved && parseInt(this.style.height || '0') <= 120) this.minimize();
    setTimeout(() => { this.mouseMoved = false; }, 0); // reset AFTER the trailing click is processed
  };

  private onKeyDown = (e: KeyboardEvent): void => {
    if (e.key === 'Escape' && this.hasAttribute('open')) this.close();
  };
}

if (typeof customElements !== 'undefined' && !customElements.get('rb-detail-drawer')) {
  customElements.define('rb-detail-drawer', RbDetailDrawer);
}
